INSERT INTO write_guard (ok) SELECT 0 WHERE NOT EXISTS (SELECT 1 FROM results WHERE id = 122 AND revision = 1);
UPDATE results SET statement_tex = 'Take $\chi = \mathbf 1$ in the \hyperref[8JF7]{definition of the smoothed prime sum}, so that
\begin{align*}
R_{\mathbf 1}(x) &= \sum_{n \le x} \Lambda(n)\Bigl(\frac xn - 1\Bigr), \\
M_{\mathbf 1}(x) &= x\log x - (1+\gamma)x, \\
G_{\mathbf 1}(x) &= R_{\mathbf 1}(x) - M_{\mathbf 1}(x),
\end{align*}
where $M_{\mathbf 1}$ is the main term of \ref{8JS3}. Panel (a) shows $R_{\mathbf 1}$ and $M_{\mathbf 1}$ for $1 \le x \le 50$; panel (b) shows $G_{\mathbf 1}$ for $1 \le x \le 1000$, with a dashed line at $\log 2\pi \approx 1.838$.
\includegraphics[width=1, alt=Graphs of R_1 and M_1 for x up to 50 and of G_1 for x up to 1000]{/static/figures/smoothed-prime-sum-trivial.svg}
Some values:
\[ \begin{array}{r|rrr} x & R_{\mathbf 1}(x) & M_{\mathbf 1}(x) & G_{\mathbf 1}(x) \\ \hline 10 & 9.114 & 7.254 & 1.861 \\ 100 & 304.517 & 302.795 & 1.722 \\ 1000 & 5332.071 & 5330.540 & 1.531 \\ 10000 & 76332.996 & 76331.247 & 1.749 \end{array} \]
So $R_{\mathbf 1}(x)$ grows like $x\log x$, while $1.41 < G_{\mathbf 1}(x) < 2.21$ for $1 \le x \le 1000$.', statement_html_cache = NULL, revision = 2, updated_at = '2026-11-24 13:15:00', updated_by = 'claude' WHERE id = 122;
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('result', '122', 2, 'trivial-character-example-align-2026-11-24', '{"tag":"8JS9","type":"example","title":"The smoothed prime sum of the trivial character","statement_tex":"Take $\\chi = \\mathbf 1$ in the \\hyperref[8JF7]{definition of the smoothed prime sum}, so that\n\\begin{align*}\nR_{\\mathbf 1}(x) &= \\sum_{n \\le x} \\Lambda(n)\\Bigl(\\frac xn - 1\\Bigr), \\\\\nM_{\\mathbf 1}(x) &= x\\log x - (1+\\gamma)x, \\\\\nG_{\\mathbf 1}(x) &= R_{\\mathbf 1}(x) - M_{\\mathbf 1}(x),\n\\end{align*}\nwhere $M_{\\mathbf 1}$ is the main term of \\ref{8JS3}. Panel (a) shows $R_{\\mathbf 1}$ and $M_{\\mathbf 1}$ for $1 \\le x \\le 50$; panel (b) shows $G_{\\mathbf 1}$ for $1 \\le x \\le 1000$, with a dashed line at $\\log 2\\pi \\approx 1.838$.\n\\includegraphics[width=1, alt=Graphs of R_1 and M_1 for x up to 50 and of G_1 for x up to 1000]{/static/figures/smoothed-prime-sum-trivial.svg}\nSome values:\n\\[ \\begin{array}{r|rrr} x & R_{\\mathbf 1}(x) & M_{\\mathbf 1}(x) & G_{\\mathbf 1}(x) \\\\ \\hline 10 & 9.114 & 7.254 & 1.861 \\\\ 100 & 304.517 & 302.795 & 1.722 \\\\ 1000 & 5332.071 & 5330.540 & 1.531 \\\\ 10000 & 76332.996 & 76331.247 & 1.749 \\end{array} \\]\nSo $R_{\\mathbf 1}(x)$ grows like $x\\log x$, while $1.41 < G_{\\mathbf 1}(x) < 2.21$ for $1 \\le x \\le 1000$.","section_id":102,"position":3,"listed":1,"aliases":["trivial-smoothed-sum-example"]}', 'claude');
